Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>
  Height along tower axis
  <input id="heightAlongAxis" type="range" min="0" max="179.6" step="1" value="100">
  <span><span id="heightValue">100</span> m</span>
