<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// tower shell → LatheGeometry hyperbolic radius profile, MeshBasicMaterial pale orange transparent
// right/left silhouette curves → Line orange following x=±r(y)
// meridian/profile contours → many Line curves on left half, orange, projected from revolved shell
// top/base rim lines → horizontal orange Lines at y=179.6 m and ground
// construction axis/waist → dashed orange Lines through center and waist
// dimension arrows → black Lines plus triangular arrowhead Meshes
// extension lines → thin black Lines from tower levels to dimension arrows
// teal supports → small tilted BoxGeometry posts along base
// selected chord → blue horizontal Line with SphereGeometry endpoint markers and live HTML label

const SCALE = 1 / 20;
const H_M = 179.6;
const WAIST_M = 100;
const TOP_TO_WAIST_M = 79.6;
const TOP_R_M = 36;
const WAIST_R_M = 30;
const TOP_Y = H_M * SCALE;
const WAIST_Y = WAIST_M * SCALE;
const TOP_DIM_Y = 190 * SCALE;
const BASE_Y = 0;
const Z_FRONT = 0.09;
const Z_DIM = 0.16;

function rMeters(yMeters) {
  return 30 * Math.sqrt(1 + ((yMeters - 100) * (yMeters - 100)) / (120 * 120));
}
function rWorldFromMeters(yMeters) {
  return rMeters(yMeters) * SCALE;
}

const orange = 0xff8a55;
const peach = 0xf6b37f;
const dashOrange = 0xe58b61;
const teal = 0x51aeb3;
const black = 0x111111;
const blue = 0x1976d2;

const fullOnly = new THREE.Group();
const profileAlways = new THREE.Group();
const constructionGroup = new THREE.Group();
scene.add(fullOnly, profileAlways, constructionGroup);

const matShell = new THREE.MeshBasicMaterial({
  color: peach,
  transparent: true,
  opacity: 0.36,
  side: THREE.DoubleSide,
  depthWrite: false
});
const matOrange = new THREE.LineBasicMaterial({ color: orange, transparent: true, opacity: 0.95 });
const matContour = new THREE.LineBasicMaterial({ color: orange, transparent: true, opacity: 0.82 });
const matDash = new THREE.LineDashedMaterial({ color: dashOrange, dashSize: 0.12, gapSize: 0.07, transparent: true, opacity: 0.85 });
const matBlack = new THREE.LineBasicMaterial({ color: black });
const matBlue = new THREE.LineBasicMaterial({ color: blue });
const matTeal = new THREE.MeshBasicMaterial({ color: teal, transparent: true, opacity: 0.85 });
const matMarker = new THREE.MeshBasicMaterial({ color: blue });

function makeLine(points, material, parent = scene) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const line = new THREE.Line(geom, material);
  if (material.isLineDashedMaterial) line.computeLineDistances();
  line.renderOrder = 5;
  parent.add(line);
  return line;
}

function profilePoints(sign = 1, scaleX = 1, z = Z_FRONT, samples = 160) {
  const pts = [];
  for (let i = 0; i < samples; i++) {
    const yM = H_M * i / (samples - 1);
    pts.push(new THREE.Vector3(sign * rWorldFromMeters(yM) * scaleX, yM * SCALE, z));
  }
  return pts;
}

const lathePts = [];
for (let i = 0; i < 145; i++) {
  const yM = H_M * i / 144;
  lathePts.push(new THREE.Vector2(rWorldFromMeters(yM), yM * SCALE));
}
const shell = new THREE.Mesh(new THREE.LatheGeometry(lathePts, 128), matShell);
shell.renderOrder = 0;
fullOnly.add(shell);
registerInteractive(shell, {
  title: 'Surface of revolution',
  tooltip: 'The cooling tower shell is generated by revolving the hyperbolic side profile.',
  body: 'The side radius is r(y)=30√(1+(y−100)²/120²) meters. Revolving this curve about the vertical axis creates the translucent cooling tower.'
});

const leftBranch = makeLine(profilePoints(-1), matOrange, profileAlways);
const rightBranch = makeLine(profilePoints(1), matOrange, profileAlways);

for (let c = -0.95; c <= -0.08; c += 0.065) {
  const pts = [];
  for (let i = 0; i < 130; i++) {
    const yM = H_M * i / 129;
    const rr = rWorldFromMeters(yM);
    const z = Math.sqrt(Math.max(0, 1 - c * c)) * rr * 0.08 + Z_FRONT;
    pts.push(new THREE.Vector3(c * rr, yM * SCALE, z));
  }
  makeLine(pts, matContour, fullOnly);
}

makeLine([new THREE.Vector3(-TOP_R_M * SCALE, TOP_Y, Z_FRONT), new THREE.Vector3(TOP_R_M * SCALE, TOP_Y, Z_FRONT)], matOrange, fullOnly);
makeLine([new THREE.Vector3(-rWorldFromMeters(0), BASE_Y, Z_FRONT), new THREE.Vector3(rWorldFromMeters(0), BASE_Y, Z_FRONT)], matOrange, fullOnly);

makeLine([new THREE.Vector3(0, BASE_Y, Z_FRONT + 0.01), new THREE.Vector3(0, TOP_Y, Z_FRONT + 0.01)], matDash, constructionGroup);
makeLine([new THREE.Vector3(-WAIST_R_M * SCALE, WAIST_Y, Z_FRONT + 0.012), new THREE.Vector3(WAIST_R_M * SCALE, WAIST_Y, Z_FRONT + 0.012)], matDash, constructionGroup);

const supportGroup = new THREE.Group();
fullOnly.add(supportGroup);
for (let i = 0; i < 17; i++) {
  const t = i / 16;
  const x = -rWorldFromMeters(0) + 2 * rWorldFromMeters(0) * t;
  const lean = x < 0 ? -0.11 : 0.11;
  const post = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.38, 0.055), matTeal);
  post.position.set(x + lean * 0.13, -0.22, Z_FRONT + 0.04);
  post.rotation.z = -lean;
  supportGroup.add(post);
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(post.geometry), new THREE.LineBasicMaterial({ color: teal }));
  edges.position.copy(post.position);
  edges.rotation.copy(post.rotation);
  edges.renderOrder = 8;
  supportGroup.add(edges);
}

function arrowHead(x, y, angle, size = 0.12, colorMat = matBlack) {
  const verts = new Float32Array([
    0, 0, 0,
    -size, size * 0.45, 0,
    -size, -size * 0.45, 0
  ]);
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.BufferAttribute(verts, 3));
  geom.setIndex([0, 1, 2]);
  geom.computeVertexNormals();
  const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({ color: colorMat.color ?? black, side: THREE.DoubleSide }));
  mesh.position.set(x, y, Z_DIM + 0.02);
  mesh.rotation.z = angle;
  mesh.renderOrder = 10;
  constructionGroup.add(mesh);
  return mesh;
}

function dimLineHorizontal(x1, x2, y) {
  makeLine([new THREE.Vector3(x1, y, Z_DIM), new THREE.Vector3(x2, y, Z_DIM)], matBlack, constructionGroup);
  arrowHead(x1, y, Math.PI);
  arrowHead(x2, y, 0);
}
function dimLineVertical(x, y1, y2) {
  makeLine([new THREE.Vector3(x, y1, Z_DIM), new THREE.Vector3(x, y2, Z_DIM)], matBlack, constructionGroup);
  arrowHead(x, y1, -Math.PI / 2);
  arrowHead(x, y2, Math.PI / 2);
}
function thinBlack(points) {
  return makeLine(points, matBlack, constructionGroup);
}

dimLineHorizontal(-TOP_R_M * SCALE, TOP_R_M * SCALE, TOP_DIM_Y);
thinBlack([new THREE.Vector3(-TOP_R_M * SCALE, TOP_Y, Z_DIM), new THREE.Vector3(-TOP_R_M * SCALE, TOP_DIM_Y + 0.18, Z_DIM)]);
thinBlack([new THREE.Vector3(TOP_R_M * SCALE, TOP_Y, Z_DIM), new THREE.Vector3(TOP_R_M * SCALE, TOP_DIM_Y + 0.18, Z_DIM)]);

dimLineHorizontal(-WAIST_R_M * SCALE, WAIST_R_M * SCALE, WAIST_Y);

const xTopWaistDim = -2.55;
dimLineVertical(xTopWaistDim, WAIST_Y, TOP_Y);
thinBlack([new THREE.Vector3(xTopWaistDim - 0.06, TOP_Y, Z_DIM), new THREE.Vector3(-TOP_R_M * SCALE, TOP_Y, Z_DIM)]);
thinBlack([new THREE.Vector3(xTopWaistDim - 0.06, WAIST_Y, Z_DIM), new THREE.Vector3(-WAIST_R_M * SCALE, WAIST_Y, Z_DIM)]);

const xFullDim = -3.75;
dimLineVertical(xFullDim, BASE_Y, TOP_Y);
thinBlack([new THREE.Vector3(xFullDim - 0.12, TOP_Y, Z_DIM), new THREE.Vector3(-TOP_R_M * SCALE - 0.15, TOP_Y, Z_DIM)]);
thinBlack([new THREE.Vector3(xFullDim - 0.12, BASE_Y, Z_DIM), new THREE.Vector3(-rWorldFromMeters(0) - 0.15, BASE_Y, Z_DIM)]);

const chordGeom = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-WAIST_R_M * SCALE, WAIST_Y, Z_DIM + 0.03),
  new THREE.Vector3(WAIST_R_M * SCALE, WAIST_Y, Z_DIM + 0.03)
]);
const chordLine = new THREE.Line(chordGeom, matBlue);
chordLine.renderOrder = 20;
scene.add(chordLine);

const markerGeom = new THREE.SphereGeometry(0.075, 24, 12);
const leftMarker = new THREE.Mesh(markerGeom, matMarker);
const rightMarker = new THREE.Mesh(markerGeom, matMarker);
leftMarker.renderOrder = 21;
rightMarker.renderOrder = 21;
scene.add(leftMarker, rightMarker);
registerInteractive(leftMarker, {
  title: 'Chord endpoint',
  tooltip: 'Point where the selected slice meets the left hyperbola branch.',
  body: 'This marker lies at x = −r(y), where r(y) is computed from the fitted hyperbola.'
});
registerInteractive(rightMarker, {
  title: 'Chord endpoint',
  tooltip: 'Point where the selected slice meets the right hyperbola branch.',
  body: 'The distance between the two markers is the selected tower diameter D(y)=2r(y).'
});

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: null,
  rollDeg: 0,
  heightFraction: 0.72,
  target: [-0.55, 4.7, 0]
});
controls.enableRotate = false;
controls.enablePan = true;
controls.enableZoom = true;

addLabel('72 m', new THREE.Vector3(0, TOP_DIM_Y + 0.33, Z_DIM), { color: '#111', fontSize: '16px' });
addLabel('60 m', new THREE.Vector3(0.48, WAIST_Y + 0.28, Z_DIM), { color: '#111', fontSize: '16px' });
addLabel('79.6 m', new THREE.Vector3(xTopWaistDim - 0.38, (WAIST_Y + TOP_Y) / 2, Z_DIM), { color: '#111', fontSize: '16px' });
addLabel('179.6 m', new THREE.Vector3(xFullDim - 0.48, TOP_Y / 2, Z_DIM), { color: '#111', fontSize: '16px' });

const liveLabel = addLabel('D = 60 m', new THREE.Vector3(0, WAIST_Y - 0.32, Z_DIM), {
  color: '#0d47a1',
  fontSize: '14px',
  bold: true,
  background: 'rgba(255,255,255,0.78)'
});

const heightSlider = document.getElementById('heightAlongAxis');
const heightValue = document.getElementById('heightValue');
const viewSelect = document.getElementById('towerView');
const demoText = document.getElementById('demoText');

function updateChord() {
  const yM = Number(heightSlider.value);
  const y = yM * SCALE;
  const r = rWorldFromMeters(yM);
  const pts = [
    new THREE.Vector3(-r, y, Z_DIM + 0.03),
    new THREE.Vector3(r, y, Z_DIM + 0.03)
  ];
  chordLine.geometry.dispose();
  chordLine.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  leftMarker.position.set(-r, y, Z_DIM + 0.07);
  rightMarker.position.set(r, y, Z_DIM + 0.07);
  const diameter = 2 * rMeters(yM);
  heightValue.textContent = yM.toFixed(yM % 1 ? 1 : 0);
  liveLabel.pos.set(0, y + (yM > 168 ? -0.35 : 0.34), Z_DIM + 0.08);
  liveLabel.div.innerHTML = `D = ${diameter.toFixed(1)} m`;
}

function updateView() {
  const fitted = viewSelect.value === 'Fitted hyperbola profile';
  fullOnly.visible = !fitted;
  leftBranch.material.color.set(fitted ? 0xff6d3a : orange);
  rightBranch.material.color.set(fitted ? 0xff6d3a : orange);
  leftBranch.material.opacity = fitted ? 1 : 0.95;
  rightBranch.material.opacity = fitted ? 1 : 0.95;
}

heightSlider.addEventListener('input', () => {
  updateChord();
});
viewSelect.addEventListener('change', () => {
  updateView();
});

updateChord();
updateView();

const demoSteps = [
  {
    title: 'Full tower at the waist',
    narration: 'At height 100 m above the ground, the horizontal slice passes through the narrowest part of the tower. The measured diameter is 60 m, matching the labeled waist.',
    state: { heightAlongAxis: 100, towerView: 'Full tower' }
  },
  {
