<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// tower shell → LatheGeometry hyperbolic radius profile, MeshBasicMaterial pale peach/orange transparent
// left/right silhouette curves → Lines following x=±r(y), strong orange
// left meridian/profile contours → closely spaced Lines on left half of revolved shell, orange
// top/base rim lines → horizontal orange Lines at top, hyperbolic base, and wider base platform/rim outline
// center axis and waist reference → orange dashed vertical and horizontal Lines through the tower
// printed dimensions → black Lines with triangular double arrowheads; waist dimension is black dashed and labeled 60 m
// extension lines → thin black Lines from top, waist, and ground levels to dimension arrows
// teal base supports → narrow tilted BoxGeometry posts, clustered on left/front base plus single far-right support
// selected chord → optional low-opacity blue horizontal Line with small SphereGeometry endpoint markers and live HTML label

const SCALE = 1 / 20;
const H_M = 179.6;
const WAIST_M = 100;
const TOP_TO_WAIST_M = 79.6;
const TOP_R_M = 36;
const WAIST_R_M = 30;
const TOP_Y = H_M * SCALE;
const WAIST_Y = WAIST_M * SCALE;
const TOP_DIM_Y = 190 * SCALE;
const BASE_Y = 0;
const Z_FRONT = 0.09;
const Z_DIM = 0.18;
const Z_LIVE = 0.28;

function rMeters(yMeters) {
  return 30 * Math.sqrt(1 + ((yMeters - 100) * (yMeters - 100)) / (120 * 120));
}
function rWorldFromMeters(yMeters) {
  return rMeters(yMeters) * SCALE;
}

const orange = 0xff8a55;
const peach = 0xf6b37f;
const dashOrange = 0xe58b61;
const teal = 0x51aeb3;
const black = 0x111111;
const blue = 0x1976d2;

const fullOnly = new THREE.Group();
const profileAlways = new THREE.Group();
const constructionGroup = new THREE.Group();
const liveGroup = new THREE.Group();
scene.add(fullOnly, profileAlways, constructionGroup, liveGroup);

const matShell = new THREE.MeshBasicMaterial({
  color: peach,
  transparent: true,
  opacity: 0.35,
  side: THREE.DoubleSide,
  depthWrite: false
});
const matOrange = new THREE.LineBasicMaterial({ color: orange, transparent: true, opacity: 0.98 });
const matContour = new THREE.LineBasicMaterial({ color: orange, transparent: true, opacity: 0.78 });
const matDashOrange = new THREE.LineDashedMaterial({
  color: dashOrange,
  dashSize: 0.12,
  gapSize: 0.07,
  transparent: true,
  opacity: 0.85
});
const matBlack = new THREE.LineBasicMaterial({ color: black });
const matBlackThin = new THREE.LineBasicMaterial({ color: black, transparent: true, opacity: 0.9 });
const matBlackDash = new THREE.LineDashedMaterial({
  color: black,
  dashSize: 0.105,
  gapSize: 0.065,
  transparent: true,
  opacity: 0.98
});
const matBlue = new THREE.LineBasicMaterial({ color: blue, transparent: true, opacity: 0.38 });
const matTeal = new THREE.MeshBasicMaterial({ color: teal, transparent: true, opacity: 0.9 });
const matTealEdge = new THREE.LineBasicMaterial({ color: teal, transparent: true, opacity: 0.95 });
const matMarker = new THREE.MeshBasicMaterial({ color: blue, transparent: true, opacity: 0.55 });

function makeLine(points, material, parent = scene, order = 5) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const line = new THREE.Line(geom, material);
  if (material.isLineDashedMaterial) line.computeLineDistances();
  line.renderOrder = order;
  parent.add(line);
  return line;
}

function profilePoints(sign = 1, z = Z_FRONT, samples = 180) {
  const pts = [];
  for (let i = 0; i < samples; i++) {
    const yM = H_M * i / (samples - 1);
    pts.push(new THREE.Vector3(sign * rWorldFromMeters(yM), yM * SCALE, z));
  }
  return pts;
}

const lathePts = [];
for (let i = 0; i < 160; i++) {
  const yM = H_M * i / 159;
  lathePts.push(new THREE.Vector2(rWorldFromMeters(yM), yM * SCALE));
}
const shell = new THREE.Mesh(new THREE.LatheGeometry(lathePts, 144), matShell);
shell.renderOrder = 0;
fullOnly.add(shell);
registerInteractive(shell, {
  title: 'Surface of revolution',
  tooltip: 'The translucent shell is made by revolving the hyperbolic side profile.',
  body: 'The radius is r(y)=30√(1+(y−100)²/120²) meters. The radius is 30 m at the waist, 36 m at the top, and about 39.05 m at the base.'
});

const leftBranch = makeLine(profilePoints(-1), matOrange, profileAlways, 8);
const rightBranch = makeLine(profilePoints(1), matOrange, profileAlways, 8);

for (let c = -0.97; c <= -0.06; c += 0.052) {
  const pts = [];
  for (let i = 0; i < 150; i++) {
    const yM = H_M * i / 149;
    const rr = rWorldFromMeters(yM);
    const z = Math.sqrt(Math.max(0, 1 - c * c)) * rr * 0.075 + Z_FRONT + 0.004;
    pts.push(new THREE.Vector3(c * rr, yM * SCALE, z));
  }
  makeLine(pts, matContour, fullOnly, 7);
}

const topR = TOP_R_M * SCALE;
const baseR = rWorldFromMeters(0);
const platformR = 2.28;
makeLine([new THREE.Vector3(-topR, TOP_Y, Z_FRONT), new THREE.Vector3(topR, TOP_Y, Z_FRONT)], matOrange, fullOnly, 9);
makeLine([new THREE.Vector3(-baseR, BASE_Y, Z_FRONT), new THREE.Vector3(baseR, BASE_Y, Z_FRONT)], matOrange, fullOnly, 9);
makeLine([new THREE.Vector3(-platformR, BASE_Y - 0.02, Z_FRONT + 0.01), new THREE.Vector3(platformR, BASE_Y - 0.02, Z_FRONT + 0.01)], matOrange, fullOnly, 9);
makeLine([new THREE.Vector3(-platformR + 0.08, BASE_Y - 0.18, Z_FRONT + 0.01), new THREE.Vector3(platformR - 0.08, BASE_Y - 0.18, Z_FRONT + 0.01)], matOrange, fullOnly, 9);
makeLine([
  new THREE.Vector3(-platformR, BASE_Y - 0.02, Z_FRONT + 0.01),
  new THREE.Vector3(-platformR + 0.08, BASE_Y - 0.18, Z_FRONT + 0.01)
], matOrange, fullOnly, 9);
makeLine([
  new THREE.Vector3(platformR, BASE_Y - 0.02, Z_FRONT + 0.01),
  new THREE.Vector3(platformR - 0.08, BASE_Y - 0.18, Z_FRONT + 0.01)
], matOrange, fullOnly, 9);

makeLine([
  new THREE.Vector3(0, BASE_Y, Z_FRONT + 0.025),
  new THREE.Vector3(0, TOP_Y, Z_FRONT + 0.025)
], matDashOrange, constructionGroup, 6);
makeLine([
  new THREE.Vector3(-WAIST_R_M * SCALE, WAIST_Y, Z_FRONT + 0.018),
  new THREE.Vector3(WAIST_R_M * SCALE, WAIST_Y, Z_FRONT + 0.018)
], matDashOrange, constructionGroup, 6);

const supportGroup = new THREE.Group();
fullOnly.add(supportGroup);

function addSupport(x, lean, height = 0.47) {
  const post = new THREE.Mesh(new THREE.BoxGeometry(0.055, height, 0.06), matTeal);
  post.position.set(x, BASE_Y - 0.34, Z_FRONT + 0.075);
  post.rotation.z = lean;
  post.renderOrder = 10;
  supportGroup.add(post);

  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(post.geometry), matTealEdge);
  edges.position.copy(post.position);
  edges.rotation.copy(post.rotation);
  edges.renderOrder = 11;
  supportGroup.add(edges);
  return post;
}

const clusteredSupports = [-2.04, -1.86, -1.66, -1.45, -1.23, -1.02, -0.81, -0.60, -0.39, -0.19, 0.02];
clusteredSupports.forEach((x, i) => {
  const lean = (i % 2 === 0 ? -0.09 : 0.09);
  addSupport(x, lean);
});
addSupport(2.24, -0.08, 0.50);

registerInteractive(supportGroup, {
  title: 'Open base supports',
  tooltip: 'Small teal posts carry the shell above the base opening.',
  body: 'The visible posts are clustered along the front-left part of the base, with a separated far-right support, matching the elevation drawing.'
});

function arrowHead(x, y, angle, size = 0.115, color = black, parent = constructionGroup) {
  const verts = new Float32Array([
    0, 0, 0,
    -size, size * 0.45, 0,
    -size, -size * 0.45, 0
  ]);
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.BufferAttribute(verts, 3));
  geom.setIndex([0, 1, 2]);
  geom.computeVertexNormals();
  const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide }));
  mesh.position.set(x, y, Z_DIM + 0.035);
  mesh.rotation.z = angle;
  mesh.renderOrder = 12;
  parent.add(mesh);
  return mesh;
}

function dimLineHorizontal(x1, x2, y, material = matBlack, dashed = false) {
  const line = makeLine([
    new THREE.Vector3(x1, y, Z_DIM),
    new THREE.Vector3(x2, y, Z_DIM)
  ], material, constructionGroup, 10);
  if (dashed) line.computeLineDistances();
  arrowHead(x1, y, 0);
  arrowHead(x2, y, Math.PI);
  return line;
}

function dimLineVertical(x, y1, y2) {
  makeLine([
    new THREE.Vector3(x, y1, Z_DIM),
    new THREE.Vector3(x, y2, Z_DIM)
  ], matBlack, constructionGroup, 10);
  arrowHead(x, y1, Math.PI / 2);
  arrowHead(x, y2, -Math.PI / 2);
}

function thinBlack(points) {
  return makeLine(points, matBlackThin, constructionGroup, 9);
}

dimLineHorizontal(-topR, topR, TOP_DIM_Y);
thinBlack([
  new THREE.Vector3(-topR, TOP_Y, Z_DIM),
  new THREE.Vector3(-topR, TOP_DIM_Y + 0.17, Z_DIM)
]);
thinBlack([
  new THREE.Vector3(topR, TOP_Y, Z_DIM),
  new THREE.Vector3(topR, TOP_DIM_Y + 0.17, Z_DIM)
]);

dimLineHorizontal(-WAIST_R_M * SCALE, WAIST_R_M * SCALE, WAIST_Y, matBlackDash, true);

const xTopWaistDim = -2.52;
dimLineVertical(xTopWaistDim, WAIST_Y, TOP_Y);
thinBlack([
  new THREE.Vector3(xTopWaistDim - 0.08, TOP_Y, Z_DIM),
  new THREE.Vector3(-topR, TOP_Y, Z_DIM)
]);
thinBlack([
  new THREE.Vector3(xTopWaistDim - 0.08, WAIST_Y, Z_DIM),
  new THREE.Vector3(-WAIST_R_M * SCALE, WAIST_Y, Z_DIM)
]);

const xFullDim = -3.72;
dimLineVertical(xFullDim, BASE_Y, TOP_Y);
thinBlack([
  new THREE.Vector3(xFullDim - 0.12, TOP_Y, Z_DIM),
  new THREE.Vector3(-topR - 0.18, TOP_Y, Z_DIM)
]);
thinBlack([
  new THREE.Vector3(xFullDim - 0.12, BASE_Y, Z_DIM),
  new THREE.Vector3(-baseR - 0.2, BASE_Y, Z_DIM)
]);

const chordGeom = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-WAIST_R_M * SCALE, WAIST_Y, Z_LIVE),
  new THREE.Vector3(WAIST_R_M * SCALE, WAIST_Y, Z_LIVE)
]);
const chordLine = new THREE.Line(chordGeom, matBlue);
chordLine.renderOrder = 18;
liveGroup.add(chordLine);

const markerGeom = new THREE.SphereGeometry(0.055, 20, 10);
const leftMarker = new THREE.Mesh(markerGeom, matMarker);
const rightMarker = new THREE.Mesh(markerGeom, matMarker);
leftMarker.renderOrder = 19;
rightMarker.renderOrder = 19;
liveGroup.add(leftMarker, rightMarker);
registerInteractive(leftMarker, {
  title: 'Slice endpoint',
  tooltip: 'The selected horizontal slice meets the left hyperbola branch here.',
  body: 'At height y, this endpoint has x = −r(y). Moving the slider changes the radius according to the fitted hyperbola.'
});
registerInteractive(rightMarker, {
  title: 'Slice endpoint',
  tooltip: 'The selected horizontal slice meets the right hyperbola branch here.',
  body: 'The live diameter is D(y)=2r(y). It is smallest at the waist and grows toward the base and top.'
});

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: null,
  rollDeg: 0,
  heightFraction: 0.72,
  target: [-0.58, 4.55, 0]
});
controls.enableRotate = false;
controls.enablePan = true;
controls.enableZoom = true;

addLabel('72 m', new THREE.Vector3(0, TOP_DIM_Y + 0.32, Z_DIM), { color: '#111', fontSize: '16px' });
addLabel('60 m', new THREE.Vector3(0.05, WAIST_Y + 0.27, Z_DIM), { color: '#111', fontSize: '16px' });
addLabel('79.6 m', new THREE.Vector3(xTopWaistDim - 0.38, (WAIST_Y + TOP_Y) / 2, Z_DIM), { color: '#111', fontSize: '16px' });
addLabel('179.6 m', new THREE.Vector3(xFullDim - 0.48, TOP_Y / 2, Z_DIM), { color: '#111', fontSize: '16px' });

const liveLabel = addLabel('D = 60.0 m', new THREE.Vector3(0, WAIST_Y - 0.34, Z_LIVE), {
  color: '#0d47a1',
  fontSize: '13px',
  bold: true,
  background: 'rgba(255,255,255,0.70)'
});

const heightSlider = document.getElementById('heightAlongAxis');
const heightValue = document.getElementById('heightValue');
const viewSelect = document.getElementById('towerView');
const showLiveChord = document.getElementById('showLiveChord');
const demoText = document.getElementById('demoText');

function updateChord() {
  const yM = Number(heightSlider.value);
  const y = yM * SCALE;
  const r = rWorldFromMeters(yM);
  const pts = [
    new THREE.Vector3(-r, y, Z_LIVE),
    new THREE.Vector3(r, y, Z_LIVE)
  ];
  chordLine.geometry.dispose();
  chordLine.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  leftMarker.position.set(-r, y, Z_LIVE + 0.035);
  rightMarker.position.set(r, y, Z_LIVE + 0.035);

  const diameter = 2 * rMeters(yM);
  heightValue.textContent = yM.toFixed(yM % 1 ? 1 : 0);
  liveLabel.pos.set(0, y + (yM > 166 ? -0.36 : -0.33), Z_LIVE + 0.05);
  liveLabel.div.innerHTML = `D = ${diameter.toFixed(1)} m`;

  const visible = showLiveChord.checked;
  liveGroup.visible = visible;
  liveLabel.div.style.display = visible ? '' : 'none';
}

function updateView() {
  const fitted = viewSelect.value === 'Fitted hyperbola profile';
  fullOnly.visible = !fitted;
  leftBranch.material.color.set(fitted ? 0xff6d3a : orange);
  rightBranch.material.color.set(fitted ? 0xff6d3a : orange);
  leftBranch.material.opacity = fitted ? 1 : 0.98;
  rightBranch.material.opacity = fitted ? 1 : 0.98;
}

heightSlider.addEventListener('input', updateChord);
viewSelect.addEventListener('change', updateView);
showLiveChord.addEventListener('change', updateChord);

updateChord();
updateView();

const demoSteps = [
  {
    title: 'Full tower at the waist',
    narration: 'At height 100 m above the ground, the horizontal slice passes through the narrowest part of the tower. The measured diameter is 60 m, matching the labeled waist.',
    state: { heightAlongAxis: 100, towerView: 'Full tower' }
  },
  {
    title: 'Move the slice to the top',
    narration: 'At height 179.6 m, the slice reaches the top opening. The diameter expands to 72 m, showing how the hyperbolic profile flares outward above the waist.',
    state: { heightAlongAxis: 179.6, towerView: 'Full tower' }
  },
  {
    title: 'Show the fitted profile',
    narration: 'Switching to the fitted hyperbola view removes the shaded shell, meridian lines, base platform, and supports. The side branches and four printed dimensions remain aligned with the same model.',
    state: { heightAlongAxis: 100, towerView: 'Fitted hyperbola profile' }
  },
  {
    title: 'Check the lower flare',
    narration: 'Moving the slice near the base shows that the diameter grows again below the waist. The same hyperbola controls both the lower widening and the upper flare.',
    state: { heightAlongAxis: 0, towerView: 'Fitted hyperbola profile' }
  }
];

let tweenToken = 0;
window.goToStep = function goToStep(index) {
  const step = demoSteps[index];
  if (!step) return;
  tweenToken++;
  const token = tweenToken;
  const startH = Number(heightSlider.value);
  const endH = step.state.heightAlongAxis;
  const startTime = performance.now();
  const duration = 850;

  viewSelect.value = step.state.towerView;
  updateView();
  demoText.innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  document.querySelectorAll('.demoStep').forEach(btn => {
    btn.classList.toggle('active', Number(btn.dataset.step) === index);
  });

  function tick(now) {
    if (token !== tweenToken) return;
    const t = Math.min(1, (now - startTime) / duration);
    const e = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    heightSlider.value = String(startH + (endH - startH) * e);
    updateChord();
    if (t < 1) requestAnimationFrame(tick);
    else {
      heightSlider.value = String(endH);
      updateChord();
    }
  }
  requestAnimationFrame(tick);
};

document.querySelectorAll('.demoStep').forEach(btn => {
  btn.addEventListener('click', () => window.goToStep(Number(btn.dataset.step)));
});

window.goToStep(0);
// @FIGURE_CODE_END

