  document.querySelectorAll('.demoStep').forEach(btn => {
    btn.classList.toggle('active', Number(btn.dataset.step) === index);
  });

  function tick(now) {
    if (token !== tweenToken) return;
    const t = Math.min(1, (now - startTime) / duration);
    const e = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    heightSlider.value = String(startH + (endH - startH) * e);
    updateChord();
    if (t < 1) requestAnimationFrame(tick);
    else {
      heightSlider.value = String(endH);
      updateChord();
    }
  }
  requestAnimationFrame(tick);
};

