// @FIGURE_CODE_BEGIN
// tower shell → LatheGeometry from hyperbolic radius profile, translucent pale peach/orange
// right/front smooth fill → true revolved shell rendered front-on with low opacity
// left/right silhouette curves → Lines following x=±r(y), strong orange
// left meridian/profile contours → many Lines x=-u·r(y), closely spaced, orange, fanning wider at base
// top/base rim lines → horizontal orange Lines at circular top and lower open base
// wide base platform/opening → two wider horizontal orange Lines plus short end returns
// center axis and waist reference → dashed orange vertical Line and horizontal Line through hyperbola center
// printed dimensions → black Lines with triangular double arrowheads; waist dimension black dashed and labeled 60 m
// extension lines → thin black Lines from dimension arrows to tower top, waist, and ground/base levels
// teal base supports → small narrow nearly-vertical BoxGeometry posts in a close row around the open base
// selected chord → optional faint blue horizontal Line with small SphereGeometry endpoint markers and live HTML label

const SCALE = 1 / 20;
const H_M = 179.6;
const WAIST_M = 100;
const TOP_R_M = 36;
const WAIST_R_M = 30;
const TOP_Y = H_M * SCALE;
const WAIST_Y = WAIST_M * SCALE;
const BASE_Y = 0;
const TOP_DIM_Y = 190 * SCALE;
const Z_SHELL = 0;
const Z_FRONT = 0.11;
const Z_DIM = 0.24;
const Z_LIVE = 0.33;

function rMeters(yMeters) {
  return 30 * Math.sqrt(1 + ((yMeters - 100) * (yMeters - 100)) / (120 * 120));
}
function rWorldFromMeters(yMeters) {
  return rMeters(yMeters) * SCALE;
}

const orange = 0xff8a55;
const peach = 0xf6b37f;
const dashOrange = 0xe58b61;
const teal = 0x51aeb3;
const black = 0x111111;
const blue = 0x1976d2;

const fullOnly = new THREE.Group();
const profileAlways = new THREE.Group();
const constructionGroup = new THREE.Group();
const liveGroup = new THREE.Group();
scene.add(fullOnly, profileAlways, constructionGroup, liveGroup);

const matShell = new THREE.MeshBasicMaterial({
  color: peach,
  transparent: true,
  opacity: 0.32,
  side: THREE.DoubleSide,
  depthWrite: false
});
const matOrange = new THREE.LineBasicMaterial({ color: orange, transparent: true, opacity: 1 });
const matContour = new THREE.LineBasicMaterial({ color: orange, transparent: true, opacity: 0.86 });
const matDashOrange = new THREE.LineDashedMaterial({
  color: dashOrange,
  dashSize: 0.12,
  gapSize: 0.07,
  transparent: true,
  opacity: 0.82
});
const matBlack = new THREE.LineBasicMaterial({ color: black });
const matBlackThin = new THREE.LineBasicMaterial({ color: black, transparent: true, opacity: 0.9 });
const matBlackDash = new THREE.LineDashedMaterial({
  color: black,
  dashSize: 0.105,
  gapSize: 0.06,
  transparent: true,
  opacity: 1
});
const matBlue = new THREE.LineBasicMaterial({ color: blue, transparent: true, opacity: 0.24 });
const matTeal = new THREE.MeshBasicMaterial({ color: teal, transparent: true, opacity: 0.92 });
const matTealEdge = new THREE.LineBasicMaterial({ color: teal, transparent: true, opacity: 0.98 });
const matMarker = new THREE.MeshBasicMaterial({ color: blue, transparent: true, opacity: 0.42 });

function makeLine(points, material, parent = scene, order = 5) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const line = new THREE.Line(geom, material);
  if (material.isLineDashedMaterial) line.computeLineDistances();
  line.renderOrder = order;
  parent.add(line);
  return line;
}

function profilePoints(sign = 1, z = Z_FRONT, samples = 220) {
  const pts = [];
  for (let i = 0; i < samples; i++) {
    const yM = H_M * i / (samples - 1);
    pts.push(new THREE.Vector3(sign * rWorldFromMeters(yM), yM * SCALE, z));
  }
  return pts;
}

const lathePts = [];
for (let i = 0; i < 180; i++) {
  const yM = H_M * i / 179;
  lathePts.push(new THREE.Vector2(rWorldFromMeters(yM), yM * SCALE));
}
const shell = new THREE.Mesh(new THREE.LatheGeometry(lathePts, 160), matShell);
shell.position.z = Z_SHELL;
shell.renderOrder = 0;
fullOnly.add(shell);
registerInteractive(shell, {
  title: 'Surface of revolution',
  tooltip: 'The translucent shell is made by revolving the hyperbolic side profile.',
  body: 'The profile satisfies x²/30² − (y−100)²/120² = 1, in meters. Revolving that curve gives the cooling-tower shell.'
});

const leftBranch = makeLine(profilePoints(-1), matOrange, profileAlways, 8);
const rightBranch = makeLine(profilePoints(1), matOrange, profileAlways, 8);

const contourUs = [0.94, 0.88, 0.82, 0.76, 0.70, 0.64, 0.58, 0.52, 0.46, 0.40, 0.34, 0.28, 0.22, 0.16, 0.10, 0.055];
for (const u of contourUs) {
  const pts = [];
  for (let i = 0; i < 190; i++) {
    const yM = H_M * i / 189;
    const y = yM * SCALE;
    const r = rWorldFromMeters(yM);
    pts.push(new THREE.Vector3(-u * r, y, Z_FRONT + 0.012));
  }
  makeLine(pts, matContour, fullOnly, 7);
}

const topR = TOP_R_M * SCALE;
const waistR = WAIST_R_M * SCALE;
const baseR = rWorldFromMeters(0);
const platformR = 2.62;

makeLine([new THREE.Vector3(-topR, TOP_Y, Z_FRONT), new THREE.Vector3(topR, TOP_Y, Z_FRONT)], matOrange, fullOnly, 10);
makeLine([new THREE.Vector3(-baseR, BASE_Y, Z_FRONT), new THREE.Vector3(baseR, BASE_Y, Z_FRONT)], matOrange, fullOnly, 10);
makeLine([new THREE.Vector3(-platformR, BASE_Y - 0.035, Z_FRONT + 0.012), new THREE.Vector3(platformR, BASE_Y - 0.035, Z_FRONT + 0.012)], matOrange, fullOnly, 10);
makeLine([new THREE.Vector3(-platformR + 0.10, BASE_Y - 0.23, Z_FRONT + 0.012), new THREE.Vector3(platformR - 0.10, BASE_Y - 0.23, Z_FRONT + 0.012)], matOrange, fullOnly, 10);
makeLine([new THREE.Vector3(-platformR, BASE_Y - 0.035, Z_FRONT + 0.012), new THREE.Vector3(-platformR + 0.10, BASE_Y - 0.23, Z_FRONT + 0.012)], matOrange, fullOnly, 10);
makeLine([new THREE.Vector3(platformR, BASE_Y - 0.035, Z_FRONT + 0.012), new THREE.Vector3(platformR - 0.10, BASE_Y - 0.23, Z_FRONT + 0.012)], matOrange, fullOnly, 10);

makeLine([new THREE.Vector3(0, BASE_Y, Z_FRONT + 0.03), new THREE.Vector3(0, TOP_Y, Z_FRONT + 0.03)], matDashOrange, constructionGroup, 6);
makeLine([new THREE.Vector3(-waistR, WAIST_Y, Z_FRONT + 0.028), new THREE.Vector3(waistR, WAIST_Y, Z_FRONT + 0.028)], matDashOrange, constructionGroup, 6);

const supportGroup = new THREE.Group();
fullOnly.add(supportGroup);

function addSupport(x, lean, height = 0.46) {
  const post = new THREE.Mesh(new THREE.BoxGeometry(0.04, height, 0.052), matTeal);
  post.position.set(x, BASE_Y - 0.31, Z_FRONT + 0.07);
  post.rotation.z = lean;
  post.renderOrder = 12;
  supportGroup.add(post);

  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(post.geometry), matTealEdge);
  edges.position.copy(post.position);
  edges.rotation.copy(post.rotation);
  edges.renderOrder = 13;
  supportGroup.add(edges);
  return post;
}

const supportXs = [];
for (let i = 0; i < 19; i++) supportXs.push(-1.95 + i * (3.9 / 18));
supportXs.forEach((x, i) => {
  const lean = (i % 2 === 0 ? 0.045 : -0.045);
  addSupport(x, lean, 0.42 + (i % 3) * 0.015);
});
addSupport(2.52, -0.035, 0.48);
addSupport(-2.52, 0.035, 0.48);

registerInteractive(supportGroup, {
  title: 'Open base supports',
  tooltip: 'Small teal posts form the open support row around the base.',
  body: 'The posts are intentionally small, nearly vertical, and closely spaced to match the repeated base supports in the elevation drawing.'
});

function arrowHead(x, y, angle, size = 0.105, color = black, parent = constructionGroup) {
  const verts = new Float32Array([
    0, 0, 0,
    -size, size * 0.44, 0,
    -size, -size * 0.44, 0
  ]);
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.BufferAttribute(verts, 3));
  geom.setIndex([0, 1, 2]);
  geom.computeVertexNormals();
  const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide }));
  mesh.position.set(x, y, Z_DIM + 0.045);
  mesh.rotation.z = angle;
  mesh.renderOrder = 14;
  parent.add(mesh);
  return mesh;
}

function dimLineHorizontal(x1, x2, y, material = matBlack) {
  const line = makeLine([new THREE.Vector3(x1, y, Z_DIM), new THREE.Vector3(x2, y, Z_DIM)], material, constructionGroup, 11);
  if (material.isLineDashedMaterial) line.computeLineDistances();
  arrowHead(x1, y, 0);
  arrowHead(x2, y, Math.PI);
  return line;
}

function dimLineVertical(x, y1, y2) {
  makeLine([new THREE.Vector3(x, y1, Z_DIM), new THREE.Vector3(x, y2, Z_DIM)], matBlack, constructionGroup, 11);
  arrowHead(x, y1, Math.PI / 2);
  arrowHead(x, y2, -Math.PI / 2);
}

function thinBlack(points) {
  return makeLine(points, matBlackThin, constructionGroup, 10);
}

dimLineHorizontal(-topR, topR, TOP_DIM_Y, matBlack);
thinBlack([new THREE.Vector3(-topR, TOP_Y, Z_DIM), new THREE.Vector3(-topR, TOP_DIM_Y + 0.16, Z_DIM)]);
thinBlack([new THREE.Vector3(topR, TOP_Y, Z_DIM), new THREE.Vector3(topR, TOP_DIM_Y + 0.16, Z_DIM)]);

dimLineHorizontal(-waistR, waistR, WAIST_Y, matBlackDash);

const xTopWaistDim = -2.34;
dimLineVertical(xTopWaistDim, WAIST_Y, TOP_Y);
thinBlack([new THREE.Vector3(xTopWaistDim - 0.08, TOP_Y, Z_DIM), new THREE.Vector3(-topR, TOP_Y, Z_DIM)]);
thinBlack([new THREE.Vector3(xTopWaistDim - 0.08, WAIST_Y, Z_DIM), new THREE.Vector3(-waistR, WAIST_Y, Z_DIM)]);

const xFullDim = -3.82;
dimLineVertical(xFullDim, BASE_Y, TOP_Y);
thinBlack([new THREE.Vector3(xFullDim - 0.12, TOP_Y, Z_DIM), new THREE.Vector3(-topR - 0.22, TOP_Y, Z_DIM)]);
thinBlack([new THREE.Vector3(xFullDim - 0.12, BASE_Y, Z_DIM), new THREE.Vector3(-baseR - 0.22, BASE_Y, Z_DIM)]);

const chordLine = new THREE.Line(new THREE.BufferGeometry(), matBlue);
chordLine.renderOrder = 18;
liveGroup.add(chordLine);

const markerGeom = new THREE.SphereGeometry(0.048, 20, 10);
const leftMarker = new THREE.Mesh(markerGeom, matMarker);
const rightMarker = new THREE.Mesh(markerGeom, matMarker);
leftMarker.renderOrder = 19;
rightMarker.renderOrder = 19;
liveGroup.add(leftMarker, rightMarker);
registerInteractive(leftMarker, {
  title: 'Slice endpoint',
  tooltip: 'The selected horizontal slice meets the left hyperbola branch here.',
  body: 'At height y, this endpoint has x = −r(y). The radius is smallest at y = 100 m.'
});
registerInteractive(rightMarker, {
  title: 'Slice endpoint',
  tooltip: 'The selected horizontal slice meets the right hyperbola branch here.',
  body: 'The live diameter is D(y)=2r(y), so it grows toward both the top and the base.'
});

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: null,
  rollDeg: 0,
  heightFraction: 0.72,
  target: [-0.57, 4.56, 0]
});
controls.enableRotate = false;
controls.enablePan = true;
controls.enableZoom = true;

addLabel('72 m', new THREE.Vector3(0, TOP_DIM_Y + 0.30, Z_DIM), { color: '#111', fontSize: '16px' });
addLabel('60 m', new THREE.Vector3(0.03, WAIST_Y + 0.25, Z_DIM), { color: '#111', fontSize: '16px' });
addLabel('79.6 m', new THREE.Vector3(xTopWaistDim - 0.36, (WAIST_Y + TOP_Y) / 2, Z_DIM), { color: '#111', fontSize: '16px' });
addLabel('179.6 m', new THREE.Vector3(xFullDim - 0.48, TOP_Y / 2, Z_DIM), { color: '#111', fontSize: '16px' });

const liveLabel = addLabel('D = 60.0 m', new THREE.Vector3(0, WAIST_Y - 0.35, Z_LIVE), {
  color: '#0d47a1',
  fontSize: '13px',
  bold: true,
  background: 'rgba(255,255,255,0.72)'
});

const heightSlider = document.getElementById('heightAlongAxis');
const heightValue = document.getElementById('heightValue');
const viewSelect = document.getElementById('towerView');
const showLiveChord = document.getElementById('showLiveChord');
const demoText = document.getElementById('demoText');

function updateChord() {
  const yM = Number(heightSlider.value);
  const y = yM * SCALE;
  const r = rWorldFromMeters(yM);
  const pts = [new THREE.Vector3(-r, y, Z_LIVE), new THREE.Vector3(r, y, Z_LIVE)];
  chordLine.geometry.dispose();
  chordLine.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  leftMarker.position.set(-r, y, Z_LIVE + 0.035);
  rightMarker.position.set(r, y, Z_LIVE + 0.035);

  const diameter = 2 * rMeters(yM);
  heightValue.textContent = yM.toFixed(yM % 1 ? 1 : 0);
  liveLabel.pos.set(0, y + (yM > 166 ? -0.34 : -0.33), Z_LIVE + 0.05);
  liveLabel.div.innerHTML = `D = ${diameter.toFixed(1)} m`;

  const visible = showLiveChord.checked;
  liveGroup.visible = visible;
  liveLabel.div.style.visibility = visible ? 'visible' : 'hidden';
}

function updateView() {
  const fitted = viewSelect.value === 'Fitted hyperbola profile';
  fullOnly.visible = !fitted;
  leftBranch.material.color.set(fitted ? 0xff6d3a : orange);
  rightBranch.material.color.set(fitted ? 0xff6d3a : orange);
  leftBranch.material.opacity = fitted ? 1 : 1;
  rightBranch.material.opacity = fitted ? 1 : 1;
}

heightSlider.addEventListener('input', updateChord);
viewSelect.addEventListener('change', updateView);
showLiveChord.addEventListener('change', updateChord);

updateChord();
updateView();

const demoSteps = [
  {
    title: 'Full tower at the waist',
    narration: 'At height 100 m above the ground, the horizontal slice passes through the narrowest part of the tower. The measured diameter is 60 m, matching the labeled waist.',
    state: { heightAlongAxis: 100, towerView: 'Full tower' }
  },
  {
    title: 'Move the slice to the top',
    narration: 'At height 179.6 m, the slice reaches the top opening. The diameter expands to 72 m, showing how the hyperbolic profile flares outward above the waist.',
    state: { heightAlongAxis: 179.6, towerView: 'Full tower' }
  },
  {
    title: 'Show the fitted profile',
    narration: 'Switching to the fitted hyperbola view removes the shaded shell and exposes the two side curves. The four printed dimensions are enough to recover the model used for the tower outline.',
    state: { heightAlongAxis: 100, towerView: 'Fitted hyperbola profile' }
  },
  {
    title: 'Check the lower flare',
    narration: 'Moving the slice near the base shows that the diameter grows again below the waist. The same hyperbola controls both the lower widening and the upper flare.',
    state: { heightAlongAxis: 0, towerView: 'Fitted hyperbola profile' }
  }
];

let tweenToken = 0;
window.goToStep = function goToStep(index) {
  const step = demoSteps[index];
  if (!step) return;
  tweenToken++;
  const token = tweenToken;
  const startH = Number(heightSlider.value);
  const endH = step.state.heightAlongAxis;
  const startTime = performance.now();
  const duration = 850;

  viewSelect.value = step.state.towerView;
  updateView();
  demoText.innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  document.querySelectorAll('.demoStep').forEach(btn => {
    btn.classList.toggle('active', Number(btn.dataset.step) === index);
  });

  function tick(now) {
    if (token !== tweenToken) return;
    const t = Math.min(1, (now - startTime) / duration);
    const e = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    heightSlider.value = String(startH + (endH - startH) * e);
    updateChord();
    if (t < 1) requestAnimationFrame(tick);
    else {
      heightSlider.value = String(endH);
      updateChord();
    }
  }
  requestAnimationFrame(tick);
};

document.querySelectorAll('.demoStep').forEach(btn => {
  btn.addEventListener('click', () => window.goToStep(Number(btn.dataset.step)));
});

window.goToStep(0);
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
{"failure_modes":["Color-Wrong","Missing-Labels"],"geometry_accuracy":4,"interactivity_usability":4,"faithfulness":3,"label_quality":3,"concept_accuracy":4,"overall_average":3.6,"notes":"Interactive elements are mostly functional, but visual and label details do not fully align with the source."}
{"next_step":"pass","rationale":"Scores are consistently high (mostly 4s), failure modes are minor visual polish issues, and concept and interactivity are solid — further iteration is unlikely to yield meaningful improvement."}

Example 2 → refine_generation
{"failure_modes":["Color-Wrong","Scale-Wrong","Interaction-Missing","Camera-Wrong"],"geometry_accuracy":3,"interactivity_usability":3,"faithfulness":3,"label_quality":3,"concept_accuracy":3,"overall_average":3,"notes":"The rendering contains overlapping text, varying colors, and lacks precise interactivity, making it somewhat difficult to grasp the 3D representation."}
{"next_step":"refine_generation","rationale":"The concept is present but execution has multiple implementation-level issues — color mismatches, missing interactions, wrong camera angle, scale errors — all fixable by the generator without changing the plan."}

Example 3 → fix_plan
{"failure_modes":["Missing-Labels","Interaction-Missing","Camera-Wrong","Color-Wrong","Concept-Misunderstood"],"geometry_accuracy":2,"interactivity_usability":2,"faithfulness":2,"label_quality":2,"concept_accuracy":2,"overall_average":2,"notes":"Discrepancies in elements and labels, with limited interactivity and conceptual errors."}
{"next_step":"fix_plan","rationale":"Concept-Misunderstood failure mode and all scores at 2/5 indicate the plan failed to correctly decompose the figure — the generator cannot fix a fundamentally wrong conceptual structure."}
